schemas:
{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "Organization",
            "@id": "https://wahanatotalita.com/#organization",
            "name": "PT Wahana Totalita Konsultan",
            "url": "https://wahanatotalita.com",
            "description": "Penyelenggara Pertemuan Korporasi, MICE Kedinasan Pemerintah & HSE Statutory Event Berlisensi PJK3 Kemnaker RI.",
            "contactPoint": {
                "@type": "ContactPoint",
                "telephone": "+62-877-5915-1278",
                "contactType": "Corporate MICE & Government Procurement Service",
                "availableLanguage": [
                    "Indonesian",
                    "English"
                ]
            }
        },
        {
            "@type": "BreadcrumbList",
            "@id": "https://wahanatotalita.com/event-organizer/#breadcrumb",
            "itemListElement": [
                {
                    "@type": "ListItem",
                    "position": 1,
                    "name": "Beranda",
                    "item": "https://wahanatotalita.com/"
                },
                {
                    "@type": "ListItem",
                    "position": 2,
                    "name": "Event Organizer B2B & B2G",
                    "item": "https://wahanatotalita.com/event-organizer/"
                }
            ]
        },
        {
            "@type": "Service",
            "@id": "https://wahanatotalita.com/event-organizer/#service",
            "name": "Corporate Meetings, Government MICE & HSE Event Organizer Indonesia",
            "provider": {
                "@id": "https://wahanatotalita.com/#organization"
            },
            "serviceType": "Enterprise Event Management & Government Procurement Service",
            "description": "Penyelenggara acara resmi B2B & B2G nasional: Rapat Kerja BUMN, Paket Meeting SBM Kemenkeu, Acara VVIP Menteri, Peringatan Bulan K3 Nasional & Emergency Fire Drill. Terdaftar LPSE / INAPROC LKPP.",
            "areaServed": [
                {
                    "@type": "Country",
                    "name": "Indonesia"
                }
            ]
        },
        {
            "@type": "FAQPage",
            "@id": "https://wahanatotalita.com/event-organizer/#faq",
            "mainEntity": [
                {
                    "@type": "Question",
                    "name": "Mengapa Wahana Totalita menjadi pilihan utama vendor event organizer bagi instansi pemerintah dan BUMN?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Wahana Totalita adalah badan hukum PT resmi dengan status PKP yang terdaftar aktif di LPSE, SiRUP, dan INAPROC LKPP. Kami memiliki rekam jejak memenangkan tender resmi pemerintah (seperti Tender Paket Meeting LKPP Rp 81,6 Juta dan pengadaan KLHK), memiliki pemahaman mendalam atas Standar Biaya Masukan (SBM) Kemenkeu, serta menjamin kelengkapan administrasi 100% siap audit BPK/Inspektorat (SPK, KAK, BAST, Faktur Pajak PPh 23 & PPN)."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Apa keunggulan Wahana Totalita dalam menyelenggarakan kegiatan HSE dan K3 Statutory?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Berbeda dari EO konvensional, Wahana Totalita merupakan Perusahaan Jasa K3 (PJK3) berlisensi resmi Kementerian Ketenagakerjaan RI. Kami berwenang menyelenggarakan Bulan K3 Nasional, Safety Day, Simulasi Tanggap Darurat Kebakaran (Fire Drill), dan Contractor Safety Stand-Down dengan instruktur bersertifikat serta menerbitkan sertifikat pelatihan dan laporan teknis yang sah untuk audit SMK3 PP 50/2012 dan ISO 45001."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Apakah Wahana Totalita melayani penyelenggaraan acara di luar Yogyakarta dan Jawa Tengah?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Ya. Kami melayani skala nasional dengan rekam jejak operasional di wilayah Jabodetabek (Jakarta, Bogor, Depok, Tangerang, Bekasi), Surakarta (Solo), Yogyakarta, Surabaya, Cilegon, Karawang, Balikpapan / IKN Nusantara, Morowali, hingga Batam. Tim produksi, sound system, rigging, LED screen, dan tenaga ahli kami siap dimobilisasi ke seluruh Indonesia."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Bagaimana mekanisme penyesuaian biaya dengan pagu Standar Biaya Masukan (SBM) Kementerian Keuangan?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Tim kami terbiasa menyusun Rencana Anggaran Biaya (RAB) berbasis Peraturan Menteri Keuangan (PMK) tentang Standar Biaya Masukan terbaru. Seluruh komponen mulai dari paket meeting fullday/fullboard hotel bintang, uang harian, honorarium narasumber, kit peserta, hingga transportasi disesuaikan presisi agar tidak melampaui batas pagu DIPA satuan kerja."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Bagaimana pengalaman Wahana Totalita dalam menangani acara VVIP dan protokoler Menteri?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Kami memiliki pengalaman langsung menyelenggarakan kunjungan kerja VVIP Menteri Kabinet di Solo dan Yogyakarta. Kami memahami protokoler ketat kedinasan, koordinasi pengamanan Paspampres/Protokol Kementerian, tata letak ruang transit VVIP, sistem audio darurat redundan, hingga tata urutan acara sesuai tata krama kenegaraan."
                    }
                }
            ]
        }
    ]
}

inline_styles:
/* Modern Executive Event Organizer Styles */
.eo-hero {
  background: linear-gradient(135deg, #091a2e 0%, #0d2847 45%, #081d33 100%);
  color: #fff;
  padding: 68px 0 54px;
  position: relative;
  overflow: hidden;
  border-bottom: 4px solid #2563eb;
}
.eo-hero::before {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background: radial-gradient(circle at 85% 15%, rgba(37, 99, 235, 0.16) 0%, transparent 60%);
  pointer-events: none;
}
.eo-hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 18px;
}
.eo-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: rgba(37, 99, 235, 0.2);
  border: 1px solid rgba(96, 165, 250, 0.45);
  color: #93c5fd;
  font-size: 12.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 6px 14px;
  border-radius: 99px;
}
.eo-badge.gold {
  background: rgba(245, 158, 11, 0.2);
  border-color: rgba(245, 158, 11, 0.5);
  color: #fde68a;
}
.eo-hero h1 {
  font-size: clamp(26px, 4vw, 45px);
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 18px;
  color: #ffffff;
}
.eo-hero h1 span.highlight {
  color: #60a5fa;
}
.eo-hero p.lead {
  font-size: clamp(15px, 1.8vw, 17.5px);
  color: #cbd5e1;
  max-width: 860px;
  line-height: 1.65;
  margin-bottom: 26px;
}
.eo-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: center;
}
.eo-btn-wa {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #25D366;
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  padding: 13px 26px;
  border-radius: 10px;
  text-decoration: none;
  transition: transform .2s ease, background .2s ease;
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.35);
}
.eo-btn-wa:hover {
  background: #20ba5a;
  transform: translateY(-2px);
  color: #fff;
}
.eo-btn-tender {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  background: rgba(255,255,255,0.08);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.28);
  font-weight: 600;
  font-size: 15px;
  padding: 13px 22px;
  border-radius: 10px;
  text-decoration: none;
}
.eo-btn-tender:hover {
  background: rgba(255,255,255,0.18);
  color: #fff;
}
.eo-trust-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 36px;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.14);
  font-size: 13.5px;
  color: #94a3b8;
}
.eo-trust-strip span {
  display: flex;
  align-items: center;
  gap: 8px;
}
.eo-trust-strip svg {
  color: #60a5fa;
  flex-shrink: 0;
}

/* Tender Proof Callout */
.eo-proof-banner {
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  border: 1px solid #334155;
  border-radius: 16px;
  padding: 24px 28px;
  margin: 36px 0;
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: center;
  color: #fff;
  box-shadow: 0 8px 24px rgba(0,0,0,0.15);
}
.eo-proof-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: rgba(37, 99, 235, 0.2);
  border: 1px solid rgba(59, 130, 246, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #60a5fa;
  flex-shrink: 0;
}
.eo-proof-text {
  flex: 1;
  min-width: 260px;
}
.eo-proof-text h3 {
  font-size: 17.5px;
  font-weight: 800;
  margin: 0 0 6px;
  color: #f8fafc;
}
.eo-proof-text p {
  margin: 0;
  font-size: 14px;
  color: #cbd5e1;
  line-height: 1.5;
}
.eo-proof-badge-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.eo-proof-tag {
  font-size: 11.5px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  padding: 4px 10px;
  border-radius: 6px;
  color: #93c5fd;
  font-weight: 600;
}
.eo-proof-action {
  flex-shrink: 0;
}
.eo-proof-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #2563eb;
  color: #fff;
  padding: 10px 18px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 13.5px;
  text-decoration: none;
  transition: background .2s ease;
}
.eo-proof-btn:hover {
  background: #1d4ed8;
  color: #fff;
}

/* Category Filter Tabs */
.eo-nav-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 28px 0 34px;
}
.eo-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #334155;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: 10px;
  text-decoration: none;
  transition: all .2s ease;
}
.eo-tab-btn:hover, .eo-tab-btn.active {
  background: #0f172a;
  border-color: #0f172a;
  color: #fff;
}
.eo-tab-count {
  background: rgba(0,0,0,0.08);
  padding: 2px 7px;
  border-radius: 99px;
  font-size: 12px;
}
.eo-tab-btn.active .eo-tab-count {
  background: rgba(255,255,255,0.2);
  color: #fff;
}

/* Services Grid */
.eo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 26px;
  margin-bottom: 50px;
}
@media (max-width: 640px) {
  .eo-grid {
    grid-template-columns: 1fr;
  }
}
.eo-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 26px;
  display: flex;
  flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
  position: relative;
}
.eo-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 28px rgba(0,0,0,0.07);
  border-color: #93c5fd;
}
.eo-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.eo-card-cat {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 4px 10px;
  border-radius: 6px;
}
.eo-cat-hse {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}
.eo-cat-gov {
  background: #eff6ff;
  color: #2563eb;
  border: 1px solid #bfdbfe;
}
.eo-cat-corp {
  background: #f0fdf4;
  color: #16a34a;
  border: 1px solid #bbf7d0;
}
.eo-cat-gala {
  background: #fdf4ff;
  color: #9333ea;
  border: 1px solid #f5d0fe;
}
.eo-cat-cap {
  background: #fffbeb;
  color: #d97706;
  border: 1px solid #fde68a;
}
.eo-card-inaproc-tag {
  font-size: 11px;
  font-weight: 700;
  background: #f8fafc;
  color: #475569;
  border: 1px solid #e2e8f0;
  padding: 3px 8px;
  border-radius: 4px;
}
.eo-card h2,
.eo-card h3 {
  font-size: 19px;
  font-weight: 800;
  line-height: 1.35;
  margin: 0 0 10px;
  color: #0f172a;
}
.eo-card h2 a,
.eo-card h3 a {
  color: inherit;
  text-decoration: none;
}
.eo-card h2 a:hover,
.eo-card h3 a:hover {
  color: #2563eb;
}
.eo-card p.tagline {
  font-size: 13.5px;
  color: #475569;
  line-height: 1.55;
  margin-bottom: 16px;
  flex: 1;
}
.eo-card-meta {
  background: #f8fafc;
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 18px;
  font-size: 12.5px;
  color: #64748b;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.eo-card-meta-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.eo-card-meta-row strong {
  color: #1e293b;
}
.eo-card-highlights {
  list-style: none;
  padding: 0;
  margin: 0 0 18px;
  font-size: 13px;
  color: #334155;
}
.eo-card-highlights li {
  position: relative;
  padding-left: 18px;
  margin-bottom: 6px;
  line-height: 1.45;
}
.eo-card-highlights li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: #2563eb;
  font-weight: 800;
}
.eo-card-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid #f1f5f9;
}
.eo-card-price {
  font-size: 12.5px;
  color: #64748b;
}
.eo-card-price strong {
  display: block;
  font-size: 15px;
  color: #0f172a;
}
.eo-card-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #0f172a;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  padding: 9px 16px;
  border-radius: 8px;
  text-decoration: none;
  transition: background .2s ease;
}
.eo-card-btn:hover {
  background: #2563eb;
  color: #fff;
}

/* SBM & Event Cost Estimator Tool */
.eo-calc-section {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  padding: 38px 34px;
  margin: 44px 0 54px;
}
.eo-calc-header {
  max-width: 760px;
  margin-bottom: 26px;
}
.eo-calc-header h2 {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 8px;
}
.eo-calc-header p {
  font-size: 14.5px;
  color: #64748b;
  margin: 0;
  line-height: 1.6;
}
.eo-calc-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}
@media (max-width: 860px) {
  .eo-calc-grid {
    grid-template-columns: 1fr;
  }
}
.eo-calc-field label {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #334155;
  margin-bottom: 8px;
}
.eo-calc-field select, .eo-calc-field input {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  background: #fff;
  font-size: 14px;
  color: #0f172a;
}
.eo-calc-result-box {
  background: #0f172a;
  border-radius: 14px;
  padding: 24px 28px;
  color: #fff;
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
}
.eo-calc-result-col {
  flex: 1;
  min-width: 220px;
}
.eo-calc-result-lbl {
  font-size: 12px;
  text-transform: uppercase;
  color: #94a3b8;
  letter-spacing: .05em;
  margin-bottom: 4px;
}
.eo-calc-result-val {
  font-size: clamp(20px, 3vw, 28px);
  font-weight: 800;
  color: #38bdf8;
}
.eo-calc-result-sub {
  font-size: 13px;
  color: #cbd5e1;
}
.eo-calc-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #25D366;
  color: #fff;
  font-weight: 700;
  font-size: 14.5px;
  padding: 12px 22px;
  border-radius: 10px;
  text-decoration: none;
  transition: transform .2s ease;
}
.eo-calc-cta:hover {
  transform: translateY(-2px);
  color: #fff;
}

/* Moat / Comparison Matrix */
.eo-moat-section {
  padding: 40px 0;
}
.eo-moat-section h2 {
  font-size: clamp(22px, 3.2vw, 32px);
  font-weight: 800;
  color: #0f172a;
  text-align: center;
  margin-bottom: 12px;
}
.eo-moat-section p.sub {
  text-align: center;
  font-size: 15px;
  color: #64748b;
  max-width: 760px;
  margin: 0 auto 34px;
  line-height: 1.6;
}
.eo-table-wrap {
  overflow-x: auto;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.03);
  margin-bottom: 40px;
}
.eo-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  background: #fff;
}
.eo-table th {
  padding: 14px 18px;
  text-align: left;
  font-weight: 700;
  background: #f8fafc;
  color: #1e293b;
  border-bottom: 2px solid #e2e8f0;
}
.eo-table th.brand-col {
  background: #0f172a;
  color: #60a5fa;
  font-size: 15px;
}
.eo-table td {
  padding: 14px 18px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
  color: #334155;
}
.eo-table tr:last-child td {
  border-bottom: none;
}
.eo-table td.brand-col {
  background: #f0f7ff;
  font-weight: 600;
  color: #0c4a6e;
}

/* Regional Reach Section */
.eo-regions-box {
  background: linear-gradient(135deg, #091a2e 0%, #172554 100%);
  color: #fff;
  border-radius: 18px;
  padding: 36px 32px;
  margin: 40px 0 50px;
}
.eo-regions-box h3 {
  font-size: 22px;
  font-weight: 800;
  margin: 0 0 10px;
  color: #f8fafc;
}
.eo-regions-box p {
  color: #cbd5e1;
  font-size: 14.5px;
  line-height: 1.6;
  margin-bottom: 24px;
}
.eo-regions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}
.eo-region-pill {
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 10px;
  padding: 12px 16px;
}
.eo-region-pill strong {
  display: block;
  font-size: 14.5px;
  color: #93c5fd;
  margin-bottom: 4px;
}
.eo-region-pill span {
  font-size: 12.5px;
  color: #cbd5e1;
}

/* FAQs */
.eo-faq-box {
  margin: 40px 0 54px;
}
.eo-faq-item {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  margin-bottom: 14px;
  overflow: hidden;
}
.eo-faq-q {
  padding: 18px 22px;
  font-weight: 700;
  font-size: 15.5px;
  color: #0f172a;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}
.eo-faq-q::after {
  content: "+";
  font-size: 20px;
  color: #2563eb;
  transition: transform .2s ease;
}
.eo-faq-item.open .eo-faq-q::after {
  transform: rotate(45deg);
}
.eo-faq-a {
  padding: 0 22px 18px;
  font-size: 14.5px;
  color: #475569;
  line-height: 1.65;
  display: none;
}
.eo-faq-item.open .eo-faq-a {
  display: block;
}

/* Bottom CTA */
.eo-cta-banner {
  background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 100%);
  color: #fff;
  border-radius: 20px;
  padding: 44px 36px;
  text-align: center;
  margin: 50px 0;
  position: relative;
  overflow: hidden;
}
.eo-cta-banner h2 {
